from PIL import Image
import numpy as np
T=np.array([[0,-.2544933,.9670745,.95],[1,0,0,.116],[0,.9670745,.2544933,.85],[0,0,0,1]])
K=230.517855
for lab in ['align4lower','align4lift2']:
 I=np.array(Image.open(f'/app/output/{lab}_side.png'));D=np.load(f'/app/output/{lab}_depth_side.npy');D=D[-1] if D.ndim==3 else D
 print(lab)
 for name,roi,typ in [('hand',(100,80,160,125),'white'),('tool',(110,115,170,145),'gray'),('obj2',(125,120,155,140),'dark')]:
  x0,y0,x1,y1=roi;P=I[y0:y1,x0:x1].astype(int);d=D[y0:y1,x0:x1].astype(float);mean=P.mean(2);sat=P.max(2)-P.min(2)
  if typ=='white':m=(P.min(2)>205)&(d<2)
  elif typ=='gray':m=(sat<30)&(mean>50)&(mean<210)&(d<2)
  else:m=(mean<150)&(d<2)
  ys,xs=np.where(m);xs+=x0;ys+=y0;pts=[]
  for u,v in zip(xs,ys):
   z=float(D[v,u]);cv=np.array([(u-160)*z/K,-(v-120)*z/K,-z,1]);pts.append((T@cv)[:3])
  pts=np.array(pts)
  print(name,'n',len(xs),'uv',np.round([xs.mean(),ys.mean()],1) if len(xs) else None,'xyz',np.round(np.median(pts,0),3) if len(xs) else None)
